//! 🪪️ Fixed identity writes preserve the shared namespace and match the independent standard hex formatter.
use super::*;
use semio_framework_plugin::artifact_app_laws::OriginalWorkFixture;
use semio_framework_value::{RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome};
#[test]
fn fixed_identity_writer_requires_original_backing_and_matches_hex_format(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert_eq!(raster_id_bytes("layer"),Some(fixture["layerBytes"].as_u64().unwrap() as usize));let mut namespace=None;for prefix in fixture["prefixes"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()){let bytes=raster_id_bytes(prefix).unwrap();let mut caller=OriginalWorkFixture::new();let mut output=String::new();assert!(write_raster_id(prefix,&mut output).is_err());caller.turn(OriginalWorkFixture::stock(),|cx|{let grant=cx.retained_grant();assert!(grant.maximum_capacity_bytes>=bytes);output.try_reserve_exact(bytes).unwrap();cx.consume_retained(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:output.capacity(),..Default::default()})?;cx.consume_fuel(1);Ok(())}).unwrap();let pointer=output.as_ptr();caller.turn(OriginalWorkFixture::stock(),|cx|{assert!(cx.retained_grant().maximum_copy_bytes>=bytes);write_raster_id(prefix,&mut output).unwrap();semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})),work:1})?;Ok(())}).unwrap();assert_eq!(output.as_ptr(),pointer);assert_eq!(output.len(),bytes);let suffix=&output[prefix.len()+1..];assert_eq!(suffix.len(),48);let words:Vec<u64>=suffix.as_bytes().chunks_exact(16).map(|bytes|u64::from_str_radix(std::str::from_utf8(bytes).unwrap(),16).unwrap()).collect();assert_eq!(output,format!("{prefix}-{:016x}{:016x}{:016x}",words[0],words[1],words[2]));if let Some(expected)=namespace{assert_eq!([words[0],words[1]],expected)}else{namespace=Some([words[0],words[1]]);}assert!(write_raster_id(prefix,&mut output).is_err());caller.retire_owned(output,OriginalWorkFixture::stock());caller.finish();}}
